from pathlib import Path
import json
from playwright.sync_api import sync_playwright
root=Path('/workspace/shared/R05-ui-review/storage')
# Reuse original transparent data URLs embedded by the desktop generator.
src=(root/'b/source.html').read_text()
import re
imgs=re.findall(r'src="(data:image/png;base64,[^"]+)"',src)
unique=list(dict.fromkeys(imgs)); fish=unique[2]
css='''*{box-sizing:border-box}body{margin:0;font-family:"Noto Sans CJK SC",sans-serif;color:#2a4140;background:#edf0e5}main{width:844px;height:390px;overflow:hidden}header{height:54px;display:flex;align-items:center;gap:7px;padding:5px 12px;background:#faf8ee;border-bottom:1px solid #a9bba5}.brand{font-size:19px;font-weight:900;margin-right:auto}button{font:inherit;min-height:44px;border:1px solid #b9cbb1;border-radius:5px;color:#2b4940;background:#eef2e7;padding:5px 12px;cursor:pointer}header button{min-width:78px;font-size:15px}header .active{background:#d5e8d8;border-color:#638a72}.content{display:grid;grid-template-columns:320px 1fr;gap:10px;padding:10px;height:336px}.collection,.drawer{border:1px solid #bbc9b1;border-radius:7px;background:#fcfaf2;padding:10px;overflow-y:auto}h1{font-size:20px;margin:0 0 4px}h2{font-size:18px;margin:0}p{font-size:14px;line-height:1.6;margin:5px 0;color:#72816e}.top{display:flex;align-items:center;justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px}.card{padding:3px;min-height:113px;text-align:center;font-size:14px;background:#f0f2e7}.card img{width:66px;height:66px;display:block;margin:auto;image-rendering:pixelated}.card small{display:block;font-size:14px;color:#77836d}.selected{background:#dcebd9;border:2px solid #6a9478}.identity{display:flex;align-items:center;gap:10px}.identity img{width:64px;height:64px;image-rendering:pixelated}.identity .name{font-size:22px;font-weight:700}.sex{display:flex;gap:6px;margin-left:auto}.sex button{min-width:44px;font-size:18px;padding:4px}.tabs{display:flex;gap:6px;margin:4px 0}.tabs button{flex:1;font-size:15px}.tabs .on{background:#6e927b;color:white}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.summary div{display:flex;justify-content:space-between;align-items:center;border:1px solid #c5d3be;background:#eef3e6;border-radius:4px;padding:7px 10px;font-size:14px}.summary b{font-size:21px;color:#4c745f}.more{display:flex;justify-content:space-between;align-items:center;margin-top:8px}.more button{background:#567e67;color:white;font-size:15px;min-width:150px}.scrollnote{font-size:14px;line-height:1.5;color:#79846f}.details{display:none}.details h2{font-size:17px;margin:10px 0 5px}.skill{background:#e9efe0;padding:8px;font-size:16px;margin:5px 0}.skill b{float:right}.trait{font-size:16px;background:#edf2e5;padding:9px}.section-label{display:flex;justify-content:space-between;margin:4px 0;font-size:14px}.top button{padding:5px 10px;font-size:14px}.scroll-arrow{font-size:14px;margin-top:7px;color:#647c68}.label{font-size:14px;color:#72816e}'''
names=['充气球','炸弹母鸡','泡泡鱼','触电羊','磁铁蟹','倒霉鸭','锻造兔','仙人掌','脱壳乌龟','乌鸦']
cards=''.join(f'<button class="card {"selected" if i==2 else ""}"><img src="{url}">{names[i]}<small>♀♂ · 2示例</small></button>' for i,url in enumerate(unique[:10]))
values=''.join(f'<div>{n}<b>{v}</b></div>' for n,v in zip(['生命','攻击','防御','速度','重量','大小'],[34,41,48,12,19,26]))
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>仓库横屏手机布局示意</title><style>'''+css+'''</style><body><main><header><div class="brand">BALLS</div><button>竞技场</button><button>主线</button><button class="active">仓库</button><button>孵蛋</button><span class="label">概念</span></header><div class="content"><section class="collection"><div class="top"><h2>精灵仓库</h2><button>种类 ▾</button></div><p>20固定示例 + 本机孵出</p><div class="grid">'''+cards+'''</div><div class="scroll-arrow">↓ 内部滚动查看全部种类</div></section><section class="drawer"><div class="identity"><img src="'''+fish+'''"><div><div class="name">泡泡鱼 ♀ <span style="font-size:15px">Lv.0</span></div><div class="label">人工样例 · 技能+3 / +3</div></div><div class="sex"><button class="selected">♀</button><button>♂</button></div></div><div class="tabs"><button class="on" onclick="showTab('summary',this)">属性</button><button onclick="showTab('skills',this)">技能 2 / 5</button><button onclick="showTab('traits',this)">特性 1 / 3</button></div><div id="summary" class="tabcontent"><div class="section-label"><b>先天概览</b><span>不是最终值</span></div><div class="summary">'''+values+'''</div><div class="more"><span class="scrollnote">基础 / 最终待定<br>后天均为0</span><button onclick="location.href='detail_source.html'">全部属性来源 ↗</button></div></div><div id="skills" class="tabcontent details"><h2>已拥有技能</h2><div class="skill">吸附泡泡 <b>+3</b></div><div class="skill">八方泡泡 <b>+3</b></div><p>技能三、技能四、技能五：待设计</p></div><div id="traits" class="tabcontent details"><h2>当前特性</h2><div class="trait">特性一 [待设计]</div><p>特性二 [待设计]<br>特性三 [待设计]</p></div></section></div></main><script>function showTab(id,button){document.querySelectorAll('.tabcontent').forEach(e=>e.style.display='none');document.getElementById(id).style.display='block';document.querySelectorAll('.tabs button').forEach(e=>e.classList.remove('on'));button.classList.add('on')}</script></body></html>'''
matrix='<table style="width:100%;border-collapse:collapse;font-size:14px;text-align:center;table-layout:fixed"><thead><tr style="height:30px;background:#e3ebdc"><th>属性</th><th>种族基础</th><th>先天</th><th>后天</th><th>最终</th></tr></thead><tbody>'+''.join(f'<tr style="height:30px;border-bottom:1px solid #d6dfce"><th>{n}</th><td>待定</td><td><b>{v}</b></td><td>0</td><td>待定</td></tr>' for n,v in zip(['生命','攻击','防御','速度','重量','大小'],[34,41,48,12,19,26]))+'</tbody></table>'
full='<div id="full" style="display:none;position:absolute;top:64px;left:10px;width:824px;height:316px;background:#fcfaf2;border:2px solid #7b997f;border-radius:7px;padding:10px;box-shadow:0 0 0 8px #344f4a44"><div class="top"><h2>泡泡鱼 ♀ Lv.0 · 全部属性来源</h2><button onclick="document.getElementById(\'full\').style.display=\'none\'">关闭 · 返回仓库 ×</button></div>'+matrix+'<p>先天是分量，不是最终值；种族基础与最终值待定。</p></div>'
html=html.replace('</main>',full+'</main>').replace("location.href='detail_source.html'", "document.getElementById('full').style.display='block'")
(root/'b/phone_source.html').write_text(html)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':844,'height':390},device_scale_factor=1);page.set_content(html)
 page.screenshot(path=str(root/'b/phone.png'))
 assert page.locator('header button').count()==4
 touch=page.locator('header button,.sex button,.tabs button,.more button').evaluate_all('(es)=>es.map(e=>({text:e.textContent,width:e.getBoundingClientRect().width,height:e.getBoundingClientRect().height}))')
 assert all(x['height']>=44 and x['width']>=44 for x in touch)
 for tab in ['skills','traits']:
  page.locator('.tabs button').nth(1 if tab=='skills' else 2).click();page.screenshot(path=str(root/'b'/('phone_'+tab+'.png')))
 page.set_content(html);page.locator('.more button').click();page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(root/'b/phone_detail.png'))
 b.close()
meta=json.loads((root/'b/review.json').read_text());meta['detail_images']=[{'image':name,'title':title} for name,title in [('detail.png','全部属性来源'),('individual_selection.png','同种个体选择'),('phone.png','手机横屏概览'),('phone_skills.png','手机技能页签'),('phone_traits.png','手机特性页签'),('phone_detail.png','手机完整属性')]];meta['phone_note']='844×390横屏手机布局示意，重排非缩图；页签查看技能/特性，种类区内部滚动；浏览器viewport模拟，非真机。';(root/'b/review.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
(root/'b/phone_qa.json').write_text(json.dumps({'viewport':[844,390],'real_device':'NOT RUN','touch_targets':touch,'text_min_px':14,'render':'browser viewport simulation, not desktop scaled screenshot'},ensure_ascii=False,indent=2)+'\n')
